------------ import ------------

------------ define ------------
---@type TrailBattleMgr
local TrailBattleMgr = import('Game.TrailBattle.TrailBattleMgr')
local PrefabName = 'RewardNode'
local GoodsNodePath = "Game.Behaviours.GoodNodeMB"
------------ define ------------


---@class TrailRewardNormalNode
---@field NoRankText                        UnityEngine.RectTransform
---@field NoRank                            UnityEngine.RectTransform
---@field TitleText                        UnityEngine.UI.Text
---@field LevelIcon                        UnityEngine.RectTransform
---@field ListView                        SuperScrollView.LoopGridView
---@field DescriptionText                UnityEngine.UI.Text
---@field NumText                        UnityEngine.UI.Text
---@field NumColor                        UnityEngine.UI.Image
local TrailRewardNormalNode = Class('TrailRewardNormalNode')

function TrailRewardNormalNode:__init()
    self.data = nil
end

function TrailRewardNormalNode:__delete()
    self.data = nil
end

function TrailRewardNormalNode:Awake()
    self.ListView:InitGridView(0, Bind(self, self.OnGetItemByIndex))
end

---FreshUI
---刷新奖励
---@param rewards table
---@param segmentNo number
---@param segmentGroupText string
---@param description string
---@param rankText string
---@param segmentGroup number
function TrailRewardNormalNode:FreshUI(rewards, segmentNo, segmentGroupText, description, rankText, segmentGroup)
    if segmentNo == 0 then
        KTool.SetActive(self.DescriptionText.transform.parent.gameObject, false)
        KTool.SetActive(self.NoRank.gameObject, true)
        KTool.GetComponent(self.NoRankText.gameObject, typeof(Text)).text = localize('该段位没有降级组')
    else
        KTool.SetActive(self.NoRank.gameObject, false)
        KTool.SetActive(self.DescriptionText.transform.parent.gameObject, true)
        ---正常的情况的显示
        self.TitleText.text = segmentGroupText
        self.DescriptionText.text = description
        KTool.GetOrAddComponent(self.LevelIcon.gameObject, typeof(ImageAlterable)):LoadSprite(TrailBattleMgr:GetInstance():GetRankGroupIconPath(segmentGroup))
        self.NumText.text = rankText
        self.data = rewards
        GameUtils.ReloadData(self.ListView, #self.data)
    end
    if segmentGroup == TrailBattleMgr.CONSTANTS.BUTTON_GROUP_ACTION.DOWN_BUTTON then
        self.NumColor.color = XLuaUtils.HexToColor(TrailBattleMgr.CONSTANTS.COLORS.LEVEL_DOWN)
    elseif segmentGroup == TrailBattleMgr.CONSTANTS.BUTTON_GROUP_ACTION.STAY_BUTTON then
        self.NumColor.color = XLuaUtils.HexToColor(TrailBattleMgr.CONSTANTS.COLORS.LEVEL_STAY)
    elseif segmentGroup == TrailBattleMgr.CONSTANTS.BUTTON_GROUP_ACTION.UP_BUTTON then
        self.NumColor.color = XLuaUtils.HexToColor(TrailBattleMgr.CONSTANTS.COLORS.LEVEL_UP)
    end

end

---@param listView SuperScrollView.LoopGridView
function TrailRewardNormalNode:OnGetItemByIndex(listView, index, row, column)
    if index < 0 then
        return
    end
    local position = index + 1
    if self.data and position <= #self.data then
        local cell = listView:NewListViewItem(PrefabName)
        local dojo = self.data[position]
        if not isNull(dojo) then
            local goodNodeTrans = cell.transform:Find("GoodNode")
            if not isNull(goodNodeTrans) then
                local reScale = goodNodeTrans.gameObject:GetComponent(typeof(ReverseScale))
                reScale:ResetScale()
                local goodItemNodeMB = GetLuaBehaviour(goodNodeTrans.gameObject, GoodsNodePath)
                if not isNull(goodItemNodeMB) then
                    if isNull(goodItemNodeMB.Env) then
                        goodItemNodeMB:Init()
                    end
                    ---@type GoodNodeMB
                    local goodItemNodeEnv = goodItemNodeMB.Env
                    goodItemNodeEnv:Reload({
                        goodsId = dojo.goodsId, isShowNo = true, text = 'x' .. FormatCurrencyNum(dojo.goodsNum)
                    })
                    goodItemNodeEnv:SetClickButtonAction(function(goodsId)
                        local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
                        if isTable(vo) then
                            GameUtils.ShowCommonTipsBoard(cell.gameObject, vo.name, vo.desc, vo.quality, vo.id)
                        end
                    end)
                end
            end
        end
        return cell
    end
end

function TrailRewardNormalNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return TrailRewardNormalNode